import hashlib, json, os

def sha256_file(p):
    h = hashlib.sha256()
    with open(p, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()

for name, crate in [("crossbeam-channel", "/opt/vendor/crossbeam-channel-0.5.15.crate"),
                    ("crossbeam-utils", "/opt/vendor/crossbeam-utils-0.8.23.crate")]:
    pkg = os.path.join("vendor", name)
    files = {}
    for root, dirs, fs in os.walk(pkg):
        for fn in fs:
            p = os.path.join(root, fn)
            files[os.path.relpath(p, pkg)] = sha256_file(p)
    meta = {"files": dict(sorted(files.items())), "package": sha256_file(crate)}
    with open(os.path.join(pkg, ".cargo-checksum.json"), "w") as f:
        json.dump(meta, f, indent=2, sort_keys=True)
    print(name, "package sha256:", meta["package"], "| files:", len(files))
